INSERT INTO "public"."processed_document_summaries"("id", "summary", "summary_embedding", "tags", "processed_document_id")
	VALUES (2, 'Das Bezirksamt Pankow plant, bis zum 31. Dezember 2024 Solaranlagen auf allen technisch nutzbaren Dachflächen öffentlicher Gebäude zu installieren. Es gibt etwa 257 solcher Gebäude im Bezirk Pankow. Das Bezirksamt ist für die Umsetzung der Solarpflicht zuständig, aber es gibt auch andere öffentliche Einrichtungen, die Gebäude im Bezirk betreiben und unter die Solarpflicht fallen. Die genaue Größe der Dachflächen ist derzeit nicht bekannt, aber bisher wurden etwa 29.000 m² mit Solaranlagen belegt. Für die Jahre 2021 und 2022 wurden Verträge für 24 PV-Anlagen abgeschlossen, und es werden weitere geeignete Dachflächen gesucht.', '[-0.0294647216796875,0.01506805419921875,0.035888671875,0.02569580078125,0.0731201171875,0.0232696533203125,0.048065185546875,-0.007312774658203125,-0.0216064453125,0.02691650390625,-0.045196533203125,0.037872314453125,-0.00562286376953125,-0.00457000732421875,-0.04718017578125,0.030792236328125,0.0130157470703125,-0.0022296905517578125,0.015838623046875,0.0121307373046875,-0.0301361083984375,-0.015289306640625,-0.060699462890625,0.01068878173828125,0.032135009765625,0.006038665771484375,-0.0217132568359375,-0.042083740234375,-0.01013946533203125,0.0021610260009765625,0.027587890625,-0.0167236328125,-0.02581787109375,0.045196533203125,0.0171661376953125,-0.0166168212890625,0.014068603515625,-0.07177734375,-0.0208282470703125,0.015838623046875,-0.0022983551025390625,-0.020050048828125,-0.0005955696105957031,0.00299072265625,-0.01007843017578125,-0.038543701171875,0.0159454345703125,-0.0112457275390625,-0.014404296875,-0.002685546875,0.0107421875,0.01983642578125,0.0223846435546875,0.01207733154296875,-0.0268096923828125,0.0280303955078125,0.005817413330078125,-0.04541015625,-0.033233642578125,0.062042236328125,-0.038116455078125,-0.00946807861328125,0.0023670196533203125,0.00786590576171875,0.0064544677734375,0.041656494140625,-0.032135009765625,-0.01141357421875,-0.02215576171875,0.01129913330078125,0.016510009765625,0.02436828613